// Auto-generated compressed seed data to stay safely under GitHub 2MB sync limit
import zlib from "zlib";
import type { DofusItem, DofusRecipe } from "../types.js";

const COMPRESSED_SEED = "";

let cachedData: { items: DofusItem[]; recipes: DofusRecipe[]; exportedAt?: number } | null = null;

export function getDofusDbSeedData(): { items: DofusItem[]; recipes: DofusRecipe[]; exportedAt?: number } {
  if (cachedData) return cachedData;
  try {
    const buffer = Buffer.from(COMPRESSED_SEED, "base64");
    const decompressed = zlib.gunzipSync(buffer).toString("utf-8");
    cachedData = JSON.parse(decompressed);
    return cachedData!;
  } catch (error) {
    console.error("Error decompressing dofusDbSeedData:", error);
    return { items: [], recipes: [] };
  }
}
